html:
{%- set item = frappe.get_cached_doc("Item", doc.item) -%}
<div class="fm-label">
	<div class="fm-label__name">{{ doc.item_name or doc.item }}</div>

	<table class="fm-label__grid">
		<tr>
			<th>{{ _("Batch") }}</th>
			<td class="fm-label__batch">{{ doc.name }}</td>
		</tr>
		{%- if doc.fm_supplier_lot_no %}
		<tr>
			<th>{{ _("Supplier Lot") }}</th>
			<td>{{ doc.fm_supplier_lot_no }}</td>
		</tr>
		{%- endif %}
		{%- if doc.manufacturing_date %}
		<tr>
			<th>{{ _("Manufactured") }}</th>
			<td>{{ frappe.format(doc.manufacturing_date, {"fieldtype": "Date"}) }}</td>
		</tr>
		{%- endif %}
		{%- if doc.expiry_date %}
		<tr>
			<th>{{ _("Best Before") }}</th>
			<td>{{ frappe.format(doc.expiry_date, {"fieldtype": "Date"}) }}</td>
		</tr>
		{%- endif %}
		{%- if item.fm_pack_size %}
		<tr>
			<th>{{ _("Net Content") }}</th>
			<td>{{ item.fm_pack_size }} {{ item.fm_pack_uom or "" }}</td>
		</tr>
		{%- endif %}
	</table>

	<div class="fm-label__status">{{ _("Quality") }}: {{ _(doc.fm_quality_status or "Not managed") }}</div>
</div>

<!-- Scoped to .fm-label so nothing here can affect any other print format. -->
<style>
	.fm-label {
		width: 70mm;
		padding: 4mm;
		border: 0.4mm solid #000;
		font-family: inherit;
		line-height: 1.35;
	}
	.fm-label__name {
		font-size: 1.1em;
		font-weight: 700;
		margin-bottom: 2mm;
		word-break: break-word;
	}
	.fm-label__grid {
		width: 100%;
		border-collapse: collapse;
		font-size: 0.85em;
	}
	.fm-label__grid th {
		text-align: left;
		font-weight: 600;
		padding: 0.6mm 2mm 0.6mm 0;
		white-space: nowrap;
		vertical-align: top;
	}
	.fm-label__grid td {
		padding: 0.6mm 0;
		word-break: break-word;
	}
	.fm-label__batch {
		font-family: monospace;
		font-weight: 700;
	}
	.fm-label__status {
		margin-top: 2mm;
		padding-top: 1.5mm;
		border-top: 0.2mm dashed #000;
		font-size: 0.8em;
	}
	@media print {
		.fm-label { border: 0.4mm solid #000; }
	}
</style>
